## Submitted testbench
```systemverilog
module tb;
  // ------------------------------------------------------------
  // Parameters and clock generation
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8;               // 125 MHz
  logic clk;
  initial clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // Reset
  // ------------------------------------------------------------
  logic rst;
  initial begin
    rst = 1;
    #(CLK_PERIOD*2);
    rst = 0;
    #(CLK_PERIOD*2);
  end

  // ------------------------------------------------------------
  // AXI‑Stream and UART interface signals
  // ------------------------------------------------------------
  logic [7:0]   s_axis_tdata;
  logic         s_axis_tvalid;
  logic         s_axis_tready_out;           // connect to DUT output
  logic [7:0]   m_axis_tdata;
  logic         m_axis_tvalid;
  logic         m_axis_tready_in;            // connect to DUT input
  logic         rxd;
  logic [15:0]  prescale_val;
  logic         txd;
  logic         tx_busy;
  logic         rx_busy;
  logic         rx_overrun_error;
  logic         rx_frame_error;

  // Keep AXI input idle
  always @(posedge clk) begin
    s_axis_tdata <= 0;
    s_axis_tvalid <= 0;
  end
  assign s_axis_tready_out = 1'b1;          // always ready
  assign m_axis_tready_in  = 1'b1;          // always ready for back‑pressure

  // ------------------------------------------------------------
  // DUT instantiation (positional port connections)
  // ------------------------------------------------------------
  uart dut (
    .clk                     (clk),
    .rst                     (rst),
    .s_axis_tdata            (s_axis_tdata),
    .s_axis_tvalid           (s_axis_tvalid),
    .s_axis_tready           (s_axis_tready_out),
    .m_axis_tdata            (m_axis_tdata),
    .m_axis_tvalid           (m_axis_tvalid),
    .m_axis_tready           (m_axis_tready_in),
    .rxd                     (rxd),
    .txd                     (txd),
    .tx_busy                 (tx_busy),
    .rx_busy                 (rx_busy),
    .rx_overrun_error        (rx_overrun_error),
    .rx_frame_error          (rx_frame_error),
    .prescale                (prescale_val)
  );

  // ------------------------------------------------------------
  // Task: drive rxd with a byte using the current prescale value
  // ------------------------------------------------------------
  task automatic send_byte (input byte unsigned b);
    integer i;
    integer bit_time;
    bit_time = prescale_val * CLK_PERIOD;
    // start bit
    rxd = 0; #bit_time;
    // data bits (LSB first)
    for (i = 0; i < 8; i = i + 1) begin
      rxd = b[i];
      #bit_time;
    end
    // stop bit
    rxd = 1;
    #bit_time;
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // ----------------------------------------------------------------
    // 1) First frame – 0x12 – at minimum prescale (1)
    // ----------------------------------------------------------------
    prescale_val = 16'd1;
    $display("[%0t] Sending 0x12 (prescale=1)", $time);
    fork send_byte(8'h12); join;               // block until transmission finished
    #1000;                                      // small idle gap

    // ----------------------------------------------------------------
    // 2) Switch to prescale = 2 for the second frame
    // ----------------------------------------------------------------
    prescale_val = 16'd2;
    $display("[%0t] Switching to prescale=2", $time);
    // ----------------------------------------------------------------
    // 3) Second frame – 0x34 – at the new prescale
    // ----------------------------------------------------------------
    $display("[%0t] Sending 0x34 (prescale=2)", $time);
    fork send_byte(8'h34); join;               // block until transmission finished

    // ----------------------------------------------------------------
    // 4) Wait for the delivered word to appear on the AXI output.
    //    When m_axis_tvalid is high and the data is 0x34 the coverage
    //    point R22_rx_prescale2_two_words is satisfied.
    // ----------------------------------------------------------------
    wait (m_axis_tvalid && m_axis_tdata == 8'h34);
    $finish;
  end
endmodule
```

